function isClear(x,z,r=.38,feet=0,height=EYE_HEIGHT){if(!Number.isFinite(x)||!Number.isFinite(z))return false;return !colliders.some(c=>Math.abs(x-c.x)<c.w+r&&Math.abs(z-c.z)<c.d+r&&c.minY<feet+height-.02&&c.maxY>feet+.11);}
function moveBody(body,dx,dz,r=.38){const human=body===player;let feet=human?player.y-EYE_HEIGHT:terrainFloor(body.x,body.z);for(const [axis,delta] of [['x',dx],['z',dz]]){const x=body.x+(axis==='x'?delta:0),z=body.z+(axis==='z'?delta:0),floor=terrainFloor(x,z),step=Math.max(feet,floor);if(!human&&(Math.abs(x)>EXPANSION_LIMIT-r||Math.abs(z)>EXPANSION_LIMIT-r))continue;if(floor-feet>.45)continue;if(isClear(x,z,r,step)){body[axis]+=delta;if(human&&velocityY<=0){const support=supportAt(x,z,feet+.45);if(support>feet&&support-feet<=.45){player.y=support+EYE_HEIGHT;feet=support;}}}}}

function lineClear(ax,az,bx,bz,ay=1.5,by=1.5){const dx=bx-ax,dz=bz-az,dy=by-ay;for(const c of colliders){let tmin=0,tmax=1;for(const [p,d,lo,hi] of [[ax,dx,c.x-c.w,c.x+c.w],[az,dz,c.z-c.d,c.z+c.d],[ay,dy,c.minY,c.maxY]]){if(Math.abs(d)<.00001){if(p<lo||p>hi){tmin=2;break;}}else{let a=(lo-p)/d,b=(hi-p)/d;if(a>b)[a,b]=[b,a];tmin=Math.max(tmin,a);tmax=Math.min(tmax,b);if(tmin>tmax)break;}}if(tmin<=tmax&&tmax>=0&&tmin<=1)return false;}const steps=Math.ceil(Math.hypot(dx,dz)/2);for(let i=1;i<steps;i++){const t=i/steps;if(ay+dy*t<terrainFloor(ax+dx*t,az+dz*t)+.04)return false;}return true;}
