const navDirections=[[1,0],[-1,0],[0,1],[0,-1]];
function navEdge(ax,az,bx,bz){const steps=Math.max(1,Math.ceil(Math.hypot(bx-ax,bz-az)/.4));for(let n=0;n<=steps;n++)if(!isClear(lerp(ax,bx,n/steps),lerp(az,bz,n/steps),.55))return false;return true;}
