function navCandidates(x,z){const nx=Math.round((x-navMin)/navStep),nz=Math.round((z-navMin)/navStep),found=[];for(let dz=-2;dz<=2;dz++)for(let dx=-2;dx<=2;dx++){const xx=nx+dx,zz=nz+dz;if(xx<0||xx>=navSize||zz<0||zz>=navSize)continue;const index=zz*navSize+xx,wx=navMin+xx*navStep,wz=navMin+zz*navStep;if(navGrid[index]&&navEdge(x,z,wx,wz))found.push({index,distance:Math.hypot(wx-x,wz-z)});}return found.sort((a,b)=>a.distance-b.distance).map(v=>v.index);}
