function findPath(ax,az,bx,bz){const starts=navCandidates(ax,az),ends=new Set(navCandidates(bx,bz));if(!starts.length||!ends.size)return [];const q=[...starts],seen=new Int32Array(navSize*navSize).fill(-2);for(const n of starts)seen[n]=-1;let end=-1;for(let head=0;head<q.length;head++){const n=q[head];if(ends.has(n)){end=n;break;}for(let dir=0;dir<4;dir++){if(!(navConnections[n]&(1<<dir)))continue;const [dx,dz]=navDirections[dir],i=n+dx+dz*navSize;if(seen[i]!==-2)continue;seen[i]=n;q.push(i);}}if(end<0)return [];const path=[{x:bx,z:bz}];let at=end;while(at>=0){path.push({x:navMin+(at%navSize)*navStep,z:navMin+Math.floor(at/navSize)*navStep});at=seen[at];}return path.reverse();}

