function updateSurvival(dt){if(mode!=='playing'||!state||dt<=0)return;const base=state.difficulty==='wanderer'?.12:state.difficulty==='desolate'?.25:.18;const sprint=(keys.ShiftLeft||keys.ShiftRight)&&(keys.KeyW||keys.ArrowUp||touchMove.y<-.1)&&!aiming&&state.hydration>=15;const rate=base*(sprint?1.6:1)*perkBonuses().waterRate,old=state.hydration;state.hydration=Math.max(0,old-rate*dt);const band=state.hydration<=0?0:state.hydration<=15?1:state.hydration<=35?2:3;if(band<survivalBand){toast(band===0?'DEHYDRATION · Health is falling! Drink with H.':band===1?'CRITICAL THIRST · Sprint unavailable. H to drink.':'LOW HYDRATION · Drink water with H.');}survivalBand=band;const drySeconds=Math.max(0,dt-old/rate);if(drySeconds>0){state.health=Math.max(0,state.health-drySeconds*2);damageFlash=Math.min(.5,.2+drySeconds*.1);if(state.health<=0){deathReason='dehydration';die();}else updateHUD();}}
function updateSurvivalHUD(){if(!state)return;$('perkButton').textContent='K · SKILL WEB / '+state.skillPoints+' POINT'+(state.skillPoints===1?'':'S');$('levelReadout').textContent='LEVEL '+state.level+' · '+state.xp+' / '+nextLevelXP()+' XP';$('hydration').textContent=Math.ceil(state.hydration)+'%';$('water').textContent=state.water;$('hydrationBar').style.width=state.hydration+'%';$('hydrationBar').style.background=state.hydration<=15?'#ec8a62':'#86dbe9';$('waterReadout').classList.toggle('critical',state.hydration<=15);$('waterNote').textContent=state.hydration<=0?'DEHYDRATION — DRINK NOW':state.hydration<=15?'THIRST — NO SPRINT':state.hydration<=60?'H TO DRINK · +40%':'WATER IS LIFE';const active=Object.values(quests).find(q=>state.quests[q.id]==='active');$('sideObjective').textContent=active?(questReady(active.id)?'✓ Return to '+active.giver+' · '+active.title:'◇ '+active.title+' · J for details'):'◇ Find human contacts and Greenline · J for quests';}
