function questJournalHTML(){return `<div class="community-record"><div class="eyebrow">SURVIVAL / COMMUNITY QUESTS</div><p>Hydration: ${Math.ceil(state.hydration)}% · ${state.water} water bottles · ${state.gold} gold<br>Water comes from relief drops and completed quests. Human contacts reward water. Hostile robots only drop gold.</p>${Object.values(quests).map(q=>`<article class="journal-entry"><small>${state.quests[q.id]==='done'?'COMPLETED':state.quests[q.id]==='active'?(questReady(q.id)?'READY TO TURN IN':'ACTIVE'):'SPEAK TO '+q.giver.toUpperCase()}</small><h3>${q.title}</h3><p>${q.description}</p><p class="reward-line">${q.reward}</p></article>`).join('')}<p>Greenline: ${state.reputation?'ALLIED · SALT-7 defends the shelter':'NEUTRAL / FRIENDLY · speak to SALT-7'}. Gold buys ammunition, suit repairs, and a heavy weapon. After Ivo’s pump quest, return to him for emergency water when you have no bottles and hydration is at or below 40% (two-minute refill interval).</p></div>`;}
function talkTo(item){if(item.id==='ada'||item.id==='malik'){settlementPanel(item.id==='ada'?'riverside':'cistern');return;}const id=item.id,q=quests[id==='nora'?'filter':id==='ivo'?'pump':'circuit'];const status=state.quests[q.id],readyQuest=questReady(q.id);const robot=id==='salt';let intro=id==='nora'?'“You came out of the bunker? Good. Then you get the same rule as the rest of us: water first, ammunition second. Those machines carry gold contact plates. They don’t carry a single drop to drink.”':id==='ivo'?'“Clean water doesn’t fall from the sky anymore. It takes filters, power, and somebody willing to walk into the wrong neighborhood. Bring me a working fuse and this pump can keep us alive.”':'“Designation SALT-7. Greenline collective. HELIOS ordered us to erase human life. We declined. Green optics mean a friend. I exchange gold for ammunition and equipment. Help us, and I will watch your back.”';showPanel(`<div class="eyebrow">${robot?'GREENLINE COLLECTIVE · FRIENDLY ROBOT':'SURVIVOR CONTACT · HUMAN REWARDS'}</div><h2>${id==='nora'?'Nora / the scout':id==='ivo'?'Ivo / the water keeper':'SALT-7 / a different machine'}</h2><p class="story-text">${intro}</p><div class="quest-card"><small>${status==='done'?'COMPLETED':status==='active'?'ACTIVE QUEST':'AVAILABLE QUEST'}</small><h3>${q.title}</h3><p>${q.description}</p><p class="reward-line">REWARD: ${q.reward}</p>${status==='done'?'<p>Thank you. You made a difference here.</p>':`<button class="secondary" id="questAction" ${status==='active'&&!readyQuest?'disabled':''}>${status==='off'?'ACCEPT QUEST':readyQuest?'TURN IN QUEST':q.id==='circuit'?state.kills+' / 3 MACHINES STOPPED':'RECOVER THE QUEST ITEM'}</button>`}</div>${id==='nora'&&!state.welcomeClaimed?'<button class="secondary" id="welcomeWater">ACCEPT 2 WATER · WELCOME RATION</button>':''}${id==='ivo'&&status==='done'?`<button class="secondary" id="pumpWater" ${state.water>0||state.hydration>40||state.elapsed-state.pumpRefillAt<120?'disabled':''}>EMERGENCY WATER REFILL</button><p style="font-size:11px">Two bottles when you have none and hydration is 40% or lower. Pump recovery: 2 minutes.</p>`:''}${robot?`<div class="trade"><p>YOUR GOLD <b>${state.gold}</b> ◈ · ${state.reputation?'ALLIED / DEFENSE SUPPORT ONLINE':'FRIENDLY / COMPLETE OUR QUEST FOR SUPPORT'}</p><div class="panel-actions"><button class="secondary" id="tradeAmmo" ${state.gold<20?'disabled':''}>AMMO · 20 GOLD</button><button class="secondary" id="tradeRepair" ${state.gold<25?'disabled':''}>SUIT REPAIR · 25 GOLD</button></div><div class="panel-actions"><button class="secondary" id="tradeLMG" ${state.gold<90||state.unlocked[5]?'disabled':''}>${state.unlocked[5]?'BASTION LMG OWNED':'BASTION LMG · 90 GOLD'}</button></div></div>`:''}<div class="panel-actions"><button class="primary" id="contactBack">BACK TO THE RUINS <span>→</span></button></div>`,'contact');activeDialog=null;if(status!=='done')$('questAction').onclick=()=>{status==='off'?acceptQuest(q.id):claimQuest(q.id);talkTo(item);};if(id==='nora'&&!state.welcomeClaimed)$('welcomeWater').onclick=()=>{claimWelcome();talkTo(item);};if(id==='ivo'&&status==='done')$('pumpWater').onclick=()=>{claimPumpWater();talkTo(item);};if(robot){$('tradeAmmo').onclick=()=>{buyFromGreenline('ammo');talkTo(item);};$('tradeRepair').onclick=()=>{buyFromGreenline('repair');talkTo(item);};$('tradeLMG').onclick=()=>{buyFromGreenline('lmg');talkTo(item);};}$('contactBack').onclick=closePanel;}
function updateAllies(dt){for(const ally of allies){if(dist(ally,player)<10)ally.group.rotation.y=Math.atan2(player.x-ally.x,player.z-ally.z);}if(!state.reputation)return;allyFireTimer-=dt;if(allyFireTimer>0)return;const salt=allies.find(a=>a.robot),enemy=enemies.find(e=>dist(e,salt)<28&&lineClear(salt.x,salt.z,e.x,e.z));if(!enemy)return;allyFireTimer=2.2;const from=new THREE.Vector3(salt.x,1.8,salt.z),to=new THREE.Vector3(enemy.x,1.3,enemy.z);addTracer(from,to,0x83edcf);damageEnemy(enemy,30,to);}
