function shootWildlife(ray,range,obstruction,damage){let best=null,owner=null;for(const l of wildlifeControllers()){const hit=l.shoot(ray,range,obstruction,0);if(hit&&(!best||hit.distance<best.distance)){best=hit;owner=l;}}return owner?owner.shoot(ray,range,obstruction,damage):null;}
function disposeRegion(root){const gs=new Set(),ms=new Set(),shared=new Set(Object.values(mats));root.traverse(o=>{if(o.geometry)gs.add(o.geometry);for(const m of Array.isArray(o.material)?o.material:[o.material])if(m&&!shared.has(m))ms.add(m);});for(const g of gs)g.dispose();for(const m of ms){m.map?.dispose();m.dispose();}scene.remove(root);}
