function syncRegions(force=false){
 if(!state||!wildernessPlan)return;const needed=new Set();const radius=force?280:340;
 for(let z=Math.floor((player.z-radius+720)/1440);z<=Math.floor((player.z+radius+720)/1440);z++)for(let x=Math.floor((player.x-radius+720)/1440);x<=Math.floor((player.x+radius+720)/1440);x++){const key=x+','+z;if(key==='0,0')continue;needed.add(key);loadRegion(x,z);}
 for(const key of [...streamedRegions.keys()])if(!needed.has(key)){const [x,z]=key.split(',').map(Number);if(Math.abs(player.x-x*1440)>1200||Math.abs(player.z-z*1440)>1200)unloadRegion(key);}
}
